    #[test]
    fn setportpix_replaces_only_cgrafport_pixmap_handle() {
        // Imaging With QuickDraw (1994), pp. 4-86..4-87: SetPortPix
        // replaces portPixMap with the supplied PixMapHandle. It does not
        // copy the PixMap record over the surrounding CGrafPort fields.
        let (mut d, mut cpu, mut bus) = setup_with_port();
        let port_ptr = 0x181000u32;
        let old_pixmap_handle = 0x260000u32;
        let new_pixmap_handle = 0x260100u32;

        bus.write_long(port_ptr + 2, old_pixmap_handle);
        bus.write_word(port_ptr + 6, 0xC000); // CGrafPort version
        for offset in 6..=14u32 {
            bus.write_byte(port_ptr + offset, (0x40 + offset) as u8);
        }
        // Restore the color-port marker after filling the sentinel bytes.
        bus.write_word(port_ptr + 6, 0xC000);
        let untouched = (6..=14u32)
            .map(|offset| bus.read_byte(port_ptr + offset))
            .collect::<Vec<_>>();
        bus.write_long(TEST_SP, new_pixmap_handle);

        let result = d.dispatch_quickdraw(true, 0x075, &mut cpu, &mut bus);
        assert!(result.unwrap().is_ok());

        assert_eq!(cpu.read_reg(Register::A7), TEST_SP + 4);
        assert_eq!(bus.read_long(port_ptr + 2), new_pixmap_handle);
        assert_eq!(
            (6..=14u32)
                .map(|offset| bus.read_byte(port_ptr + offset))
                .collect::<Vec<_>>(),
            untouched,
            "SetPortPix must not overwrite fields following portPixMap"
        );
    }

    #[test]
    fn setport_ignores_invalid_proc_pointer_without_syncing_draw_state() {
        let (mut d, mut cpu, mut bus) = setup_with_port();
        let original_port = d.current_port;
        let invalid_port = 0x0001_6178u32;
        let watched = invalid_port + 56;

        // Shape this like a loaded jump-table/proc pointer, not a GrafPort.
        bus.write_word(invalid_port, 0x4EF9);
        bus.write_long(invalid_port + 2, 0x0026_B0B0);
        bus.write_long(watched, 0xDEAD_BEEF);

        bus.write_long(TEST_SP, invalid_port);
        let result = d.dispatch_quickdraw(true, 0x073, &mut cpu, &mut bus);

        assert!(result.unwrap().is_ok());
        assert_eq!(cpu.read_reg(Register::A7), TEST_SP + 4);
        assert_eq!(d.current_port, original_port);
        assert_eq!(
            bus.read_long(crate::memory::globals::addr::THE_PORT),
            original_port
        );
        assert_eq!(
            bus.read_long(watched),
            0xDEAD_BEEF,
            "SetPort must not synthesize pen state into non-port memory"
        );
    }

    #[test]
    fn setport_preserves_current_gdevice_selected_by_setgdevice() {
        // Imaging With QuickDraw 1994 p. 5-24 documents the legacy offscreen
        // sequence that pairs SetGDevice with SetPort instead of SetGWorld.
        let (mut d, mut cpu, mut bus) = setup_with_port();
        let port_ptr = 0x181000u32;
        let custom_gdh = 0x0050_0000u32;

        bus.write_long(TEST_SP, custom_gdh);
        let set_device = d.dispatch_quickdraw(true, 0x231, &mut cpu, &mut bus);
        assert!(set_device.unwrap().is_ok());
        assert_eq!(cpu.read_reg(Register::A7), TEST_SP + 4);
        assert_eq!(d.current_gdevice, custom_gdh);
        assert_eq!(bus.read_long(0x0CC8), custom_gdh);

        cpu.write_reg(Register::A7, TEST_SP);
        bus.write_long(TEST_SP, port_ptr);
        let set_port = d.dispatch_quickdraw(true, 0x073, &mut cpu, &mut bus);
        assert!(set_port.unwrap().is_ok());

        assert_eq!(cpu.read_reg(Register::A7), TEST_SP + 4);
        assert_eq!(d.current_port, port_ptr);
        assert_eq!(d.current_gdevice, custom_gdh);
        assert_eq!(
            bus.read_long(crate::memory::globals::addr::THE_PORT),
            port_ptr
        );
        assert_eq!(bus.read_long(0x0CC8), custom_gdh);

        cpu.write_reg(Register::A7, TEST_SP);
        let get_device = d.dispatch_quickdraw(true, 0x232, &mut cpu, &mut bus);
        assert!(get_device.unwrap().is_ok());
        assert_eq!(bus.read_long(TEST_SP), custom_gdh);
    }

