        bus.write_long(TEST_SP, out_ptr);
        let result = d.dispatch_quickdraw(true, 0x074, &mut cpu, &mut bus);
        assert!(result.unwrap().is_ok());
        assert_eq!(cpu.read_reg(Register::A7), TEST_SP + 4);
