    #[test]
    fn sectrgn_preserves_complex_scanline_intersection() {
        // Inside Macintosh Volume I (1985), p. I-184: SectRgn computes
        // the geometric intersection of two regions, not only their bboxes.
        let (mut d, mut cpu, mut bus) = setup();

        let complex = make_complex_rgn(
            &mut bus,
            (0, 0, 4, 6),
            &[
                0,
                0,
                6,
                super::REGION_STOP,
                1,
                2,
                4,
                super::REGION_STOP,
                3,
                2,
                4,
                super::REGION_STOP,
                4,
                0,
                6,
                super::REGION_STOP,
                super::REGION_STOP,
            ],
        );
        let clip_data = bus.alloc(10);
        let clip = bus.alloc(4);
        make_rgn(&mut bus, clip_data, clip, 1, 1, 3, 5);
        let dst_data = bus.alloc(10);
        let dst = bus.alloc(4);
        make_rgn(&mut bus, dst_data, dst, 0, 0, 0, 0);

        bus.write_long(TEST_SP, dst);
        bus.write_long(TEST_SP + 4, clip);
        bus.write_long(TEST_SP + 8, complex);

        let result = d.dispatch_quickdraw(true, 0x0E4, &mut cpu, &mut bus);
        assert!(result.unwrap().is_ok());
        assert_eq!(cpu.read_reg(Register::A7), TEST_SP + 12);
        assert_eq!(read_rgn_bbox(&bus, dst), (1, 1, 3, 5));
        assert!(
            bus.read_word(bus.read_long(dst)) > super::REGION_HEADER_SIZE as u16,
            "intersection should stay complex, not collapse to its bbox"
        );
        assert!(TrapDispatcher::region_contains_point(&bus, dst, 1, 1));
        assert!(
            !TrapDispatcher::region_contains_point(&bus, dst, 1, 3),
            "hole inside the source region must remain clipped out"
        );
        assert!(TrapDispatcher::region_contains_point(&bus, dst, 1, 4));
    }

    #[test]
    fn offsetrgn_shifts_complex_region_scanlines() {
        // Inside Macintosh Volume I (1985), p. I-183: OffsetRgn moves the
        // region shape. Complex scanline coordinates must move with the bbox.
        let (mut d, mut cpu, mut bus) = setup();
        let rgn = make_complex_rgn(
            &mut bus,
            (0, 0, 3, 6),
            &[
                0,
                0,
                6,
                super::REGION_STOP,
                1,
                2,
                4,
                super::REGION_STOP,
                2,
                2,
                4,
                super::REGION_STOP,
                3,
                0,
                6,
                super::REGION_STOP,
                super::REGION_STOP,
            ],
        );

        bus.write_word(TEST_SP, 20u16); // dv
        bus.write_word(TEST_SP + 2, 10u16); // dh
        bus.write_long(TEST_SP + 4, rgn);

        let result = d.dispatch_quickdraw(true, 0x0E0, &mut cpu, &mut bus);
        assert!(result.unwrap().is_ok());
        assert_eq!(cpu.read_reg(Register::A7), TEST_SP + 8);
        assert_eq!(read_rgn_bbox(&bus, rgn), (20, 10, 23, 16));
        assert!(TrapDispatcher::region_contains_point(&bus, rgn, 21, 11));
        assert!(
            !TrapDispatcher::region_contains_point(&bus, rgn, 21, 13),
            "the shifted interior hole must remain a hole"
        );
        assert!(TrapDispatcher::region_contains_point(&bus, rgn, 21, 14));
        assert!(!TrapDispatcher::region_contains_point(&bus, rgn, 1, 1));
    }

    #[test]
    fn insetrgn_shrinks_complex_region_scanlines() {
        // Imaging With QuickDraw (1994), p. 3-93: InsetRgn moves the region
        // boundary inward. Complex scanline edge data must move with the bbox.
        let (mut d, mut cpu, mut bus) = setup();
        let rgn = bus.alloc(4);
        let rows = vec![
            vec![0, 10],
            vec![0, 10],
            vec![0, 10],
            vec![2, 8],
            vec![2, 8],
            vec![0, 10],
            vec![0, 10],
            vec![0, 10],
        ];
        assert!(TrapDispatcher::write_region_from_rows(
            &mut bus, rgn, 0, &rows
        ));
        assert!(
            bus.read_word(bus.read_long(rgn)) > super::REGION_HEADER_SIZE as u16,
            "test fixture should exercise the complex-region path"
        );

        bus.write_word(TEST_SP, 1u16); // dv
        bus.write_word(TEST_SP + 2, 1u16); // dh
        bus.write_long(TEST_SP + 4, rgn);

        let result = d.dispatch_quickdraw(true, 0x0E1, &mut cpu, &mut bus);
        assert!(result.unwrap().is_ok());
        assert_eq!(cpu.read_reg(Register::A7), TEST_SP + 8);
        assert_eq!(read_rgn_bbox(&bus, rgn), (1, 1, 7, 9));
        assert!(TrapDispatcher::region_contains_point(&bus, rgn, 1, 2));
        assert!(TrapDispatcher::region_contains_point(&bus, rgn, 2, 3));
        assert!(
            !TrapDispatcher::region_contains_point(&bus, rgn, 2, 2),
            "middle-band edge should move inward with the complex scanlines"
        );
        assert!(!TrapDispatcher::region_contains_point(&bus, rgn, 0, 5));
    }

    // EqualRgn ($A8E3) lives at slot 0x0E3, not 0x0E5. Prior to the
    // region-op slot audit these tests were pointed at the UnionRgn
    // slot and asserted 0xFFFF for TRUE; both were wrong. The strong
    // contract coverage for EqualRgn lives in the equalrgn_* family;
    // these two inline tests retain the original
    // happy-path / sad-path shape but dispatch to the correct slot
    // and assert the 0x0100 Pascal BOOL convention used elsewhere in
    // this file (EmptyRgn, PtInRgn, RectInRgn).
    #[test]
    fn test_equal_rgn_true() {
        let (mut d, mut cpu, mut bus) = setup();
        let rgn_a = 0x300000u32;
        let handle_a = 0x300100u32;
        make_rgn(&mut bus, rgn_a, handle_a, 10, 20, 100, 200);
        let rgn_b = 0x300200u32;
        let handle_b = 0x300300u32;
        make_rgn(&mut bus, rgn_b, handle_b, 10, 20, 100, 200);
        bus.write_long(TEST_SP, handle_b);
        bus.write_long(TEST_SP + 4, handle_a);
        bus.write_word(TEST_SP + 8, 0); // result slot
        let result = d.dispatch_quickdraw(true, 0x0E3, &mut cpu, &mut bus);
        assert!(result.unwrap().is_ok());
        assert_eq!(cpu.read_reg(Register::A7), TEST_SP + 8);
        assert_eq!(bus.read_word(TEST_SP + 8), 0x0100); // TRUE
    }

    #[test]
    fn test_equal_rgn_false() {
        let (mut d, mut cpu, mut bus) = setup();
        let rgn_a = 0x300000u32;
        let handle_a = 0x300100u32;
        make_rgn(&mut bus, rgn_a, handle_a, 10, 20, 100, 200);
        let rgn_b = 0x300200u32;
        let handle_b = 0x300300u32;
        make_rgn(&mut bus, rgn_b, handle_b, 0, 0, 50, 50);
        bus.write_long(TEST_SP, handle_b);
        bus.write_long(TEST_SP + 4, handle_a);
        bus.write_word(TEST_SP + 8, 0xFFFF);
        let result = d.dispatch_quickdraw(true, 0x0E3, &mut cpu, &mut bus);
        assert!(result.unwrap().is_ok());
        assert_eq!(cpu.read_reg(Register::A7), TEST_SP + 8);
        assert_eq!(bus.read_word(TEST_SP + 8), 0); // FALSE
    }

