        bus.write_byte(data_ptr + 2, 0x33);

        cpu.write_reg(Register::A0, 0xCAFEBABE);
        cpu.write_reg(Register::A1, 0x0BADF00D);
        cpu.write_reg(Register::D0, 0x01020304);
        cpu.write_reg(Register::D1, 0xA1B2C3D4);
