    // IM:I I-190: when a region is open and being formed, FramePoly adds the
    // polygon's outside outline to the region boundary and pops one PolyHandle
    // argument.
    #[test]
    fn framepoly_open_region_updates_recorded_bounds_and_pops_arg() {
        let (mut d, mut cpu, mut bus) = setup_with_port();
        let (screen_base, row_bytes) = setup_polygon_surface(&mut d, &mut bus);

        let poly_ptr = bus.alloc(22);
        let poly_handle = bus.alloc(4);
        make_poly(
            &mut bus,
            poly_ptr,
            poly_handle,
            (10, 10, 20, 20),
            &[(10, 10), (10, 20), (20, 20)],
        );

        d.recording_region = Some(super::super::dispatch::RegionRecording::default());
        bus.write_long(TEST_SP, poly_handle);
        let result = d.dispatch_quickdraw(true, 0x0C6, &mut cpu, &mut bus);
        assert!(result.unwrap().is_ok());
        assert_eq!(cpu.read_reg(Register::A7), TEST_SP + 4);
        assert_eq!(
            d.recording_region
                .as_ref()
                .and_then(|recording| recording.bbox),
            Some((10, 10, 20, 20)),
            "FramePoly should fold polygon bounds into the active OpenRgn recording extent"
        );
        assert_eq!(
            bus.read_byte(screen_base + 15 * row_bytes + 15),
            0x00,
            "FramePoly should not rasterize while OpenRgn recording is active"
        );
    }

    #[test]
    fn closergn_preserves_concave_framepoly_boundary() {
        // OpenRgn must record the polygon itself, not polyBBox.  This shape's
        // right-hand notch is inside its bbox but outside its boundary.
        let (mut d, mut cpu, mut bus) = setup_with_port();
        let poly_ptr = bus.alloc(34);
        let poly_handle = bus.alloc(4);
        make_poly(
            &mut bus,
            poly_ptr,
            poly_handle,
            (10, 10, 30, 30),
            &[(10, 10), (10, 30), (20, 20), (30, 30), (30, 10)],
        );
        let dst_ptr = bus.alloc(10);
        let dst = bus.alloc(4);
        make_rgn(&mut bus, dst_ptr, dst, 0, 0, 0, 0);

        assert!(d
            .dispatch_quickdraw(true, 0x0DA, &mut cpu, &mut bus)
            .unwrap()
            .is_ok());
        cpu.write_reg(Register::A7, TEST_SP);
        bus.write_long(TEST_SP, poly_handle);
        assert!(d
            .dispatch_quickdraw(true, 0x0C6, &mut cpu, &mut bus)
            .unwrap()
            .is_ok());
        cpu.write_reg(Register::A7, TEST_SP);
        bus.write_long(TEST_SP, dst);
        assert!(d
            .dispatch_quickdraw(true, 0x0DB, &mut cpu, &mut bus)
            .unwrap()
            .is_ok());

        assert!(TrapDispatcher::region_contains_point(&bus, dst, 20, 15));
        assert!(
            !TrapDispatcher::region_contains_point(&bus, dst, 20, 25),
            "the concave notch must not be filled merely because it lies inside polyBBox"
        );
    }

    #[test]
    fn closergn_preserves_framed_oval_and_round_rect_scanlines() {
        // Imaging With QuickDraw (1994), pp. 3-87--3-89: framed-shape
        // boundaries form closed loops in an open region, independent of the
        // pen. Their curved corners must survive CloseRgn as complex rows.
        let (mut d, mut cpu, mut bus) = setup_with_port();
        let oval_rect = bus.alloc(8);
        write_rect(&mut bus, oval_rect, 10, 10, 30, 30);
        let round_rect = bus.alloc(8);
        write_rect(&mut bus, round_rect, 40, 10, 60, 50);

        let oval_ptr = bus.alloc(10);
        let oval = bus.alloc(4);
        make_rgn(&mut bus, oval_ptr, oval, 0, 0, 0, 0);
        d.dispatch_quickdraw(true, 0x0DA, &mut cpu, &mut bus)
            .unwrap()
            .unwrap();
        cpu.write_reg(Register::A7, TEST_SP);
        bus.write_long(TEST_SP, oval_rect);
        d.dispatch_quickdraw(true, 0x0B7, &mut cpu, &mut bus)
            .unwrap()
            .unwrap();
        cpu.write_reg(Register::A7, TEST_SP);
        bus.write_long(TEST_SP, oval);
        d.dispatch_quickdraw(true, 0x0DB, &mut cpu, &mut bus)
            .unwrap()
            .unwrap();

        assert!(TrapDispatcher::region_contains_point(&bus, oval, 20, 20));
        assert!(!TrapDispatcher::region_contains_point(&bus, oval, 10, 10));
        assert!(bus.read_word(bus.read_long(oval)) > 10);

        let rounded_ptr = bus.alloc(10);
        let rounded = bus.alloc(4);
        make_rgn(&mut bus, rounded_ptr, rounded, 0, 0, 0, 0);
        d.dispatch_quickdraw(true, 0x0DA, &mut cpu, &mut bus)
            .unwrap()
            .unwrap();
        cpu.write_reg(Register::A7, TEST_SP);
        bus.write_word(TEST_SP, 12); // ovalHeight
        bus.write_word(TEST_SP + 2, 12); // ovalWidth
        bus.write_long(TEST_SP + 4, round_rect);
        d.dispatch_quickdraw(true, 0x0B0, &mut cpu, &mut bus)
            .unwrap()
            .unwrap();
        cpu.write_reg(Register::A7, TEST_SP);
        bus.write_long(TEST_SP, rounded);
        d.dispatch_quickdraw(true, 0x0DB, &mut cpu, &mut bus)
            .unwrap()
            .unwrap();

        assert!(TrapDispatcher::region_contains_point(&bus, rounded, 50, 10));
        assert!(!TrapDispatcher::region_contains_point(&bus, rounded, 40, 10));
        assert!(bus.read_word(bus.read_long(rounded)) > 10);
    }

