        cpu.write_reg(Register::A7, TEST_SP);
        bus.write_bytes(dst_base, &[42, 42]);
        bus.write_word(TEST_SP + 4, 1);
        assert!(d
            .dispatch_quickdraw(true, 0x0EC, &mut cpu, &mut bus)
            .unwrap()
            .is_ok());
        assert_eq!(bus.read_bytes(dst_base, 2), vec![42, 255]);
