        bus.write_bytes(dst_base, &[0xA5, 0x67, 0x8B, 0xCC]);
        write_rect(&mut bus, src_rect, 0, 0, 1, 4);
        write_rect(&mut bus, dst_rect, 0, 1, 1, 5);

        bus.write_long(TEST_SP, 0);
