    #[test]
    fn plotcicon_uses_iconmask_to_gate_destination_writes() {
        // More Macintosh Toolbox (1993), p. 5-25 and Inside Macintosh
        // Volume V (1986), p. V-76: PlotCIcon copies icon pixels only
        // where iconMask bits are 1; mask=0 bits leave destination unchanged.
        let (mut d, mut cpu, mut bus) = setup();
        let dst_base = bus.alloc(64);
        bus.fill_zeros(dst_base, 64);
        bus.write_byte(dst_base, 0x0F);

        // Build a minimal CGrafPort with a portPixMap handle so PlotCIcon
        // takes the Color QuickDraw destination path.
        let pm_handle = bus.alloc(4);
        let pm_ptr = bus.alloc(64);
        bus.fill_zeros(pm_ptr, 64);
        bus.write_long(pm_handle, pm_ptr);
        bus.write_long(pm_ptr, dst_base);
        bus.write_word(pm_ptr + 4, 1); // rowBytes
        write_rect(&mut bus, pm_ptr + 6, 0, 0, 1, 8);
        let port_ptr = bus.alloc(128);
        bus.fill_zeros(port_ptr, 128);
        bus.write_long(port_ptr, pm_handle);
        bus.write_word(port_ptr + 4, 0xC000); // CGrafPort signature

        let a5 = cpu.read_reg(Register::A5);
        let globals_ptr = bus.read_long(a5);
        bus.write_long(globals_ptr, port_ptr);

        let cicn_data = make_test_cicn_resource(0xF0, 0x00, 0x55);
        d.install_test_resource(&mut bus, *b"cicn", 128, &cicn_data);

        bus.write_word(TEST_SP, 128);
        let get_icon = d.dispatch_quickdraw(true, 0x21E, &mut cpu, &mut bus);
        assert!(get_icon.unwrap().is_ok());
        let icon_handle = bus.read_long(TEST_SP + 2);
        assert_ne!(icon_handle, 0);

        let rect_ptr = 0x300120u32;
        write_rect(&mut bus, rect_ptr, 0, 0, 1, 8);
        cpu.write_reg(Register::A7, TEST_SP);
        bus.write_long(TEST_SP, icon_handle);
        bus.write_long(TEST_SP + 4, rect_ptr);

        let plot = d.dispatch_quickdraw(true, 0x21F, &mut cpu, &mut bus);
        assert!(plot.unwrap().is_ok());
        assert_eq!(cpu.read_reg(Register::A7), TEST_SP + 8);
        assert_eq!(bus.read_byte(dst_base), 0x5F);
    }

    #[test]
    fn plotcicon_uses_real_cgrafport_layout_and_honors_empty_visrgn() {
        // Systemless CGrafPorts store portPixMap at +2 and portVersion at
        // +6, matching Imaging With QuickDraw's CGrafPort layout. PlotCIcon
        // must resolve that real layout, not only the legacy synthetic test
        // layout with the PixMap handle at +0.
        let (mut d, mut cpu, mut bus) = setup();
        let dst_base = bus.alloc(64);
        bus.fill_zeros(dst_base, 64);
        bus.write_byte(dst_base, 0x0F);

        let pm_handle = bus.alloc(4);
        let pm_ptr = bus.alloc(64);
        bus.fill_zeros(pm_ptr, 64);
        bus.write_long(pm_handle, pm_ptr);
        bus.write_long(pm_ptr, dst_base);
        bus.write_word(pm_ptr + 4, 1);
        write_rect(&mut bus, pm_ptr + 6, 0, 0, 1, 8);

        let port_ptr = bus.alloc(128);
        bus.fill_zeros(port_ptr, 128);
        bus.write_long(port_ptr + 2, pm_handle);
        bus.write_word(port_ptr + 6, 0xC000);

        let a5 = cpu.read_reg(Register::A5);
        let globals_ptr = bus.read_long(a5);
        bus.write_long(globals_ptr, port_ptr);

        let cicn_data = make_test_cicn_resource(0xF0, 0x00, 0x55);
        d.install_test_resource(&mut bus, *b"cicn", 128, &cicn_data);

        bus.write_word(TEST_SP, 128);
        let get_icon = d.dispatch_quickdraw(true, 0x21E, &mut cpu, &mut bus);
        assert!(get_icon.unwrap().is_ok());
        let icon_handle = bus.read_long(TEST_SP + 2);
        assert_ne!(icon_handle, 0);

        let rect_ptr = 0x300140u32;
        write_rect(&mut bus, rect_ptr, 0, 0, 1, 8);
        cpu.write_reg(Register::A7, TEST_SP);
        bus.write_long(TEST_SP, icon_handle);
        bus.write_long(TEST_SP + 4, rect_ptr);

        let plot = d.dispatch_quickdraw(true, 0x21F, &mut cpu, &mut bus);
        assert!(plot.unwrap().is_ok());
        assert_eq!(cpu.read_reg(Register::A7), TEST_SP + 8);
        assert_eq!(bus.read_byte(dst_base), 0x5F);

        let vis_rgn_ptr = bus.alloc(10);
        bus.write_word(vis_rgn_ptr, 10);
        let vis_rgn = bus.alloc(4);
        bus.write_long(vis_rgn, vis_rgn_ptr);
        bus.write_long(port_ptr + 24, vis_rgn);
        bus.write_byte(dst_base, 0x0F);
        cpu.write_reg(Register::A7, TEST_SP);
        bus.write_long(TEST_SP, icon_handle);
        bus.write_long(TEST_SP + 4, rect_ptr);

        let hidden_plot = d.dispatch_quickdraw(true, 0x21F, &mut cpu, &mut bus);
        assert!(hidden_plot.unwrap().is_ok());
        assert_eq!(bus.read_byte(dst_base), 0x0F);
    }

    #[test]
    fn plotcicon_decodes_packed_4bpp_icon_pixels_into_8bpp_destination() {
        // More Macintosh Toolbox (1993), p. 5-25 / Inside Macintosh V
        // (1986), p. V-76: PlotCIcon stretches the iconPMap and remaps its
        // pixels to the current depth and color table.
        let (mut d, mut cpu, mut bus) = setup();
        d.device_clut = [[0, 0, 0]; 256];
        d.device_clut[7] = [0x1111, 0x0000, 0x0000];
        d.device_clut[9] = [0x0000, 0x2222, 0x0000];
        d.device_clut[42] = [0x0000, 0x0000, 0x3333];
        assert_eq!(
            crate::trap::pict::closest_clut_index(0x1111, 0x0000, 0x0000, &d.device_clut),
            7
        );

        let dst_base = bus.alloc(8);
        bus.fill_zeros(dst_base, 8);

        let pm_handle = bus.alloc(4);
        let pm_ptr = bus.alloc(64);
        bus.fill_zeros(pm_ptr, 64);
        bus.write_long(pm_handle, pm_ptr);
        write_pixmap_8(&mut bus, pm_ptr, dst_base, 4, 1, 0);

        let port_ptr = bus.alloc(128);
        bus.fill_zeros(port_ptr, 128);
        bus.write_long(port_ptr + 2, pm_handle);
        bus.write_word(port_ptr + 6, 0xC000);

        let a5 = cpu.read_reg(Register::A5);
        let globals_ptr = bus.read_long(a5);
        bus.write_long(globals_ptr, port_ptr);

        let mut icon_entries = [[0, 0, 0]; 16];
        icon_entries[1] = d.device_clut[7];
        icon_entries[2] = d.device_clut[9];
        icon_entries[3] = d.device_clut[42];
        let cicn_data = make_test_cicn_resource_4bpp([0x12, 0x30], &icon_entries);
        d.install_test_resource(&mut bus, *b"cicn", 129, &cicn_data);

        bus.write_word(TEST_SP, 129);
        let get_icon = d.dispatch_quickdraw(true, 0x21E, &mut cpu, &mut bus);
        assert!(get_icon.unwrap().is_ok());
        let icon_handle = bus.read_long(TEST_SP + 2);
        assert_ne!(icon_handle, 0);
        let icon_ptr = bus.read_long(icon_handle);
        assert_eq!(bus.read_word(icon_ptr + 32), 4);
        let icon_data_handle = bus.read_long(icon_ptr + 78);
        let icon_data_ptr = bus.read_long(icon_data_handle);
        assert_eq!(bus.read_bytes(icon_data_ptr, 2), vec![0x12, 0x30]);
        assert_eq!(
            TrapDispatcher::read_packed_bitmap_index(&bus, icon_data_ptr, 2, 4, 0, 0, 1, 4, 0, 0),
            Some(1)
        );
        assert_eq!(
            TrapDispatcher::read_packed_bitmap_index(&bus, icon_data_ptr, 2, 4, 0, 0, 1, 4, 0, 2),
            Some(3)
        );

        let rect_ptr = 0x300160u32;
        write_rect(&mut bus, rect_ptr, 0, 0, 1, 4);
        cpu.write_reg(Register::A7, TEST_SP);
        bus.write_long(TEST_SP, icon_handle);
        bus.write_long(TEST_SP + 4, rect_ptr);

        let plot = d.dispatch_quickdraw(true, 0x21F, &mut cpu, &mut bus);
        assert!(plot.unwrap().is_ok());
        assert_eq!(cpu.read_reg(Register::A7), TEST_SP + 8);
        assert_eq!(
            bus.read_bytes(dst_base, 4),
            vec![7, 9, 42, 255],
            "packed 4bpp source nibbles should decode and remap through the icon ColorTable"
        );
    }

    #[test]
    fn plotcicon_screen_backed_port_uses_live_device_clut() {
        // A screen-backed CGrafPort's private PixMap table can predate a
        // Palette Manager activation. The screen device's live table must
        // control inverse mapping, just as it does for other screen drawing.
        // Imaging With QuickDraw (1994), pp. 4-55 to 4-59 and 5-28.
        let (mut d, mut cpu, mut bus) = setup();
        d.device_clut = [[0, 0, 0]; 256];
        d.device_clut[0] = [0xFFFF, 0xFFFF, 0xFFFF];
        d.device_clut[1] = [0x1010, 0x1010, 0x1010];
        d.device_clut[7] = [0x4040, 0x4545, 0x4545];

        let (screen_base, screen_row_bytes, screen_w, screen_h, _) = d.screen_mode;
        let stale_ctab = make_test_ctab_handle(&mut bus, &[[0x4444, 0x4444, 0x4444]], 1, 0);
        let pm_handle = bus.alloc(4);
        let pm_ptr = bus.alloc(64);
        bus.fill_zeros(pm_ptr, 64);
        bus.write_long(pm_handle, pm_ptr);
        bus.write_long(pm_ptr, screen_base);
        bus.write_word(pm_ptr + 4, 0x8000 | screen_row_bytes as u16);
        write_rect(&mut bus, pm_ptr + 6, 0, 0, screen_h as i16, screen_w as i16);
        bus.write_word(pm_ptr + 32, 8);
        bus.write_long(pm_ptr + 42, stale_ctab);

        let port_ptr = bus.alloc(128);
        bus.fill_zeros(port_ptr, 128);
        bus.write_long(port_ptr + 2, pm_handle);
        bus.write_word(port_ptr + 6, 0xC000);
        let a5 = cpu.read_reg(Register::A5);
        let globals_ptr = bus.read_long(a5);
        bus.write_long(globals_ptr, port_ptr);

        let mut icon_entries = [[0, 0, 0]; 16];
        icon_entries[1] = [0x4444, 0x4444, 0x4444];
        let cicn_data = make_test_cicn_resource_4bpp([0x11, 0x11], &icon_entries);
        d.install_test_resource(&mut bus, *b"cicn", 130, &cicn_data);

        bus.write_word(TEST_SP, 130);
        let get_icon = d.dispatch_quickdraw(true, 0x21E, &mut cpu, &mut bus);
        assert!(get_icon.unwrap().is_ok());
        let icon_handle = bus.read_long(TEST_SP + 2);
        let rect_ptr = 0x300180u32;
        write_rect(&mut bus, rect_ptr, 0, 0, 1, 4);
        cpu.write_reg(Register::A7, TEST_SP);
        bus.write_long(TEST_SP, icon_handle);
        bus.write_long(TEST_SP + 4, rect_ptr);

        let plot = d.dispatch_quickdraw(true, 0x21F, &mut cpu, &mut bus);

        assert!(plot.unwrap().is_ok());
        assert_eq!(bus.read_bytes(screen_base, 4), vec![7, 7, 7, 7]);
    }

    #[test]
    fn plotcicon_selected_transform_reduces_icon_brightness() {
        // ttSelected makes the Apple icon colors darker before inverse
        // mapping them to the destination device. Macintosh Human Interface
        // Guidelines (1992), p. 241; More Macintosh Toolbox (1993), p. 5-37.
        let (mut d, mut cpu, mut bus) = setup();
        d.device_clut = [[0, 0, 0]; 256];
        d.device_clut[8] = [0x2222, 0x2222, 0x2222];

        let dst_base = bus.alloc(8);
        let pm_handle = bus.alloc(4);
        let pm_ptr = bus.alloc(64);
        bus.fill_zeros(pm_ptr, 64);
        bus.write_long(pm_handle, pm_ptr);
        write_pixmap_8(&mut bus, pm_ptr, dst_base, 4, 1, 0);
        let port_ptr = bus.alloc(128);
        bus.fill_zeros(port_ptr, 128);
        bus.write_long(port_ptr + 2, pm_handle);
        bus.write_word(port_ptr + 6, 0xC000);
        let globals_ptr = bus.read_long(cpu.read_reg(Register::A5));
        bus.write_long(globals_ptr, port_ptr);

        let mut icon_entries = [[0, 0, 0]; 16];
        icon_entries[1] = [0x4444, 0x4444, 0x4444];
        let cicn_data = make_test_cicn_resource_4bpp([0x11, 0x11], &icon_entries);
        d.install_test_resource(&mut bus, *b"cicn", 131, &cicn_data);
        bus.write_word(TEST_SP, 131);
        d.dispatch_quickdraw(true, 0x21E, &mut cpu, &mut bus)
            .unwrap()
            .unwrap();
        let icon_handle = bus.read_long(TEST_SP + 2);
        let rect_ptr = 0x3001A0u32;
        write_rect(&mut bus, rect_ptr, 0, 0, 1, 4);
        cpu.write_reg(Register::A7, TEST_SP);
        bus.write_long(TEST_SP, icon_handle);
        bus.write_long(TEST_SP + 4, rect_ptr);
        d.icon_transform_override = 0x4000;

        d.dispatch_quickdraw(true, 0x21F, &mut cpu, &mut bus)
            .unwrap()
            .unwrap();

        assert_eq!(bus.read_bytes(dst_base, 4), vec![8, 8, 8, 8]);
    }

    #[test]
    fn plotcicon_nil_rect_is_harmless_noop() {
        // More Macintosh Toolbox (1993), p. 5-25: PlotCIcon takes a
        // Rect pointer, but a NIL pointer should not trash unrelated
        // memory when the call is otherwise well-formed.
        let (mut d, mut cpu, mut bus) = setup_with_port();
        let dst_base = bus.alloc(64);
        bus.fill_zeros(dst_base, 64);
        bus.write_byte(dst_base, 0x0F);

        let pm_handle = bus.alloc(4);
        let pm_ptr = bus.alloc(64);
        bus.fill_zeros(pm_ptr, 64);
        bus.write_long(pm_handle, pm_ptr);
        bus.write_long(pm_ptr, dst_base);
        bus.write_word(pm_ptr + 4, 1);
        write_rect(&mut bus, pm_ptr + 6, 0, 0, 1, 8);
        let port_ptr = bus.alloc(128);
        bus.fill_zeros(port_ptr, 128);
        bus.write_long(port_ptr, pm_handle);
        bus.write_word(port_ptr + 4, 0xC000);

        let a5 = cpu.read_reg(Register::A5);
        let globals_ptr = bus.read_long(a5);
        bus.write_long(globals_ptr, port_ptr);

        let cicn_data = make_test_cicn_resource(0xF0, 0x00, 0x55);
        d.install_test_resource(&mut bus, *b"cicn", 128, &cicn_data);

        bus.write_word(TEST_SP, 128);
        let get_icon = d.dispatch_quickdraw(true, 0x21E, &mut cpu, &mut bus);
        assert!(get_icon.unwrap().is_ok());
        let icon_handle = bus.read_long(TEST_SP + 2);
        assert_ne!(icon_handle, 0);

        cpu.write_reg(Register::A7, TEST_SP);
        bus.write_long(TEST_SP, icon_handle);
        bus.write_long(TEST_SP + 4, 0);

        let plot = d.dispatch_quickdraw(true, 0x21F, &mut cpu, &mut bus);
        assert!(plot.unwrap().is_ok());
        assert_eq!(cpu.read_reg(Register::A7), TEST_SP + 8);
        assert_eq!(bus.read_byte(dst_base), 0x0F);
    }

